(7470044, 1186512, 30982, '<td valign="top">Yum!!</td>', 'Yum!!', '2016-08-29 01:04:01.000000', NULL, 1),
(7470109, 1186504, 96751, '<td valign="top">I like the idea, just find the picture too dark overall.</td>', 'I like the idea, just find the picture too dark overall.', '2016-08-29 12:40:38.000000', NULL, 1),
(7470110, 1186335, 96751, '<td valign="top">Nice tones, but I find the composition unappealing and the haloing around every object is over the top.</td>', 'Nice tones, but I find the composition unappealing and the haloing around every object is over the top.', '2016-08-29 12:41:38.000000', NULL, 1),
(7470111, 1186262, 96751, '<td valign="top">The blur doesn''t work for me. They payoff of the building a third of the way up the image, isn''t strong enough.</td>', 'The blur doesn''t work for me. They payoff of the building a third of the way up the image, isn''t strong enough.', '2016-08-29 12:44:11.000000', NULL, 1),
(7470112, 1186560, 96751, '<td valign="top">Despite the haze, I think a bit more attention to pp''g could have elevated this from a meh image to something really interesting.</td>', 'Despite the haze, I think a bit more attention to pp''g could have elevated this from a meh image to something really interesting.', '2016-08-29 12:45:37.000000', NULL, 1),
(7470114, 1186260, 96751, '<td valign="top">The banding in the sky is really extreme and detracts from the rays.</td>', 'The banding in the sky is really extreme and detracts from the rays.', '2016-08-29 12:52:55.000000', NULL, 1),
(7470119, 1186542, 96751, '<td valign="top">Straighten that horizon! :)</td>', 'Straighten that horizon! :)', '2016-08-29 13:02:48.000000', NULL, 1),
(7470120, 1186079, 96751, '<td valign="top">Gorgeous pov. The left side of the image (especially the skyscrapers) are rather distorted towards the left, and could easily have been fixed in post.</td>', 'Gorgeous pov. The left side of the image (especially the skyscrapers) are rather distorted towards the left, and could easily have been fixed in post.', '2016-08-29 13:05:00.000000', NULL, 1),
(7470121, 1185872, 96751, '<td valign="top">Nice angle, but the distortion really impacts the score for me.</td>', 'Nice angle, but the distortion really impacts the score for me.', '2016-08-29 13:08:43.000000', NULL, 1),
(7470122, 1186295, 170007, '<td valign="top">Brilliant contrasts and deep blacks. 10.</td>', 'Brilliant contrasts and deep blacks. 10.', '2016-08-29 13:10:22.000000', NULL, 1),
(7470136, 1186041, 183132, '<td valign="top">Very nice!</td>', 'Very nice!', '2016-08-29 17:39:45.000000', NULL, 1),
