(7470179, 1186041, 124815, '<td valign="top">Charming processing</td>', 'Charming processing', '2016-08-29 23:35:31.000000', NULL, 1),
(7470181, 1186512, 124815, '<td valign="top">This is one of the images that is sometimes painted in oil - and one wonders why indeed - the drab of a suburban life, a mundane place in which the redeeming beauty rests in the familiarity of the setting. Particularly good is the left side of the image.</td>', 'This is one of the images that is sometimes painted in oil - and one wonders why indeed - the drab of a suburban life, a mundane place in which the redeeming beauty rests in the familiarity of the setting. Particularly good is the left side of the image.', '2016-08-29 23:41:29.000000', NULL, 1),
(7470230, 1186079, 17850, '<td valign="top">Very nice panoramic view! One of the few images that truly meet the challenge.<br/>Should be at the top 3, good luck! (9)</td>', 'Very nice panoramic view! One of the few images that truly meet the challenge.Should be at the top 3, good luck! (9)', '2016-08-30 05:02:38.000000', NULL, 1),
