(7470670, 1186507, 182284, '<td valign="top">This must have been taken in the wee hours of morning or later in the eve. Nice colors but just a little soft for me. I gave this an 8.</td>', 'This must have been taken in the wee hours of morning or later in the eve. Nice colors but just a little soft for me. I gave this an 8.', '2016-09-01 01:46:16.000000', NULL, 1),
(7470694, 1186295, 30982, '<td valign="top">Wonderfully messy yet organized.  Very fun shot.</td>', 'Wonderfully messy yet organized.  Very fun shot.', '2016-09-01 02:08:00.000000', NULL, 1),
(7470695, 1186584, 30982, '<td valign="top">Nice big view, with lots going on, lots to see.  My kind of shot.  I like how it makes the cruise ship seem almost small!</td>', 'Nice big view, with lots going on, lots to see.  My kind of shot.  I like how it makes the cruise ship seem almost small!', '2016-09-01 02:08:37.000000', NULL, 1),
