(7470697, 1185872, 30982, '<td valign="top">Nice yellows throughout to tie everything together.</td>', 'Nice yellows throughout to tie everything together.', '2016-09-01 02:09:06.000000', NULL, 1),
(7470698, 1186131, 30982, '<td valign="top">I do like how you tried to hide the cars in the bushes with the low angle - puts the focus on the school itself.  The light didn''t help you much here, though.  I know what that''s like, waiting for the light to cooperate.  Most days it doesn''t.</td>', 'I do like how you tried to hide the cars in the bushes with the low angle - puts the focus on the school itself.  The light didn''t help you much here, though.  I know what that''s like, waiting for the light to cooperate.  Most days it doesn''t.', '2016-09-01 02:10:19.000000', NULL, 1),
(7470699, 1186398, 30982, '<td valign="top">I almost want to see this in color but can appreciate that you chose to present it in B&amp;W.</td>', 'I almost want to see this in color but can appreciate that you chose to present it in B&W.', '2016-09-01 02:11:35.000000', NULL, 1),
(7470700, 1186504, 30982, '<td valign="top">Countrified urban of sorts.  Love the pathway stones and the way it leads you in.</td>', 'Countrified urban of sorts.  Love the pathway stones and the way it leads you in.', '2016-09-01 02:12:11.000000', NULL, 1),
(7470702, 1186246, 30982, '<td valign="top">Looks like a gorgeous structure!  I''m not overly fond of the stylized processing, though.</td>', 'Looks like a gorgeous structure!  I''m not overly fond of the stylized processing, though.', '2016-09-01 02:12:55.000000', NULL, 1),
(7470705, 1186598, 30982, '<td valign="top">Kind of an off the beaten path sort of feeling to this.  And it just clicked that this is a reflection.</td>', 'Kind of an off the beaten path sort of feeling to this.  And it just clicked that this is a reflection.', '2016-09-01 02:14:55.000000', NULL, 1),
(7470706, 1186270, 30982, '<td valign="top">Great use of ultra wide/fisheye.  Love the activity and I have a soft spot for train stations.  Thanks!</td>', 'Great use of ultra wide/fisheye.  Love the activity and I have a soft spot for train stations.  Thanks!', '2016-09-01 02:16:05.000000', NULL, 1),
