(7511491, 1186295, 98565, '<td valign="top">One of my friends at my local photographer''s group owns an Olympus too. If he joins a lihghtpainting shooting it''s so much easier to control the results because he can tell me how the picture evolves while the painting is still in progress. Tanks for showing this wonderful example!<br/>On the contrary I use a Fuji camera which is couting the seconds on the display while exposure... so we are kind of a perfect team!<br/> <br/>I also enjoyed the story why you choose the picture title. <br/>I''m always wondering why owners are so nervous about taking pictures... maybe because of the intellectual property of the architect???? <br/></td>', 'One of my friends at my local photographer''s group owns an Olympus too. If he joins a lihghtpainting shooting it''s so much easier to control the results because he can tell me how the picture evolves while the painting is still in progress. Tanks for showing this wonderful example!On the contrary I use a Fuji camera which is couting the seconds on the display while exposure... so we are kind of a perfect team! I also enjoyed the story why you choose the picture title. I''m always wondering why owners are so nervous about taking pictures... maybe because of the intellectual property of the architect???? ', '2017-05-01 19:03:16.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7511596, 1186295, 47974, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by primabarbara:</b></div><hr/><i> One of my friends at my local photographer''s group owns an Olympus too. If he joins a lihghtpainting shooting it''s so much easier to control the results because he can tell me how the picture evolves while the painting is still in progress. Tanks for showing this wonderful example!<br/>On the contrary I use a Fuji camera which is couting the seconds on the display while exposure... so we are kind of a perfect team!<br/> <br/>I also enjoyed the story why you choose the picture title. <br/>I''m always wondering why owners are so nervous about taking pictures... maybe because of the intellectual property of the architect???? </i></td></tr></table> <br/> <br/>Thank you for the comment.<br/> <br/>I am not sure what their problem is.  When ever I am in the area I always stop by to photograph the building (always have a camera with me)just to get the security guard to come out and tell me I can''t.  While it''s true, the photos can''t be used for commercial purposes without owners permission they can be used to sell as prints or enter in photo challenges all you want.  What gets me so fired up about Chevron is them having an employee come out and tell you it''s illegal to photograph the build and insist you stop doing it.  Which is completely false as it''s perfectly legal to photograph anything from public property and the sidewalk is public property.  I tell them every time to call the police if they feel I am breaking the law or to leave me alone or I will call the police for harassment.  I have yet to have them call the police and each time they stop trying to talk with me and just stand there and watch............which makes shooting at night so much safer.  When there at night I always thank the employee (who is just doing his job and doesn''t want to be out there anyways) for watching after me and making sure I am safe.  Will usually tweet a thank you for Chevron being so concerned about my safety that they provide me with a guard.</td>', 'Originally posted by primabarbara: One of my friends at my local photographer''s group owns an Olympus too. If he joins a lihghtpainting shooting it''s so much easier to control the results because he can tell me how the picture evolves while the painting is still in progress. Tanks for showing this wonderful example!On the contrary I use a Fuji camera which is couting the seconds on the display while exposure... so we are kind of a perfect team! I also enjoyed the story why you choose the picture title. I''m always wondering why owners are so nervous about taking pictures... maybe because of the intellectual property of the architect????   Thank you for the comment. I am not sure what their problem is.  When ever I am in the area I always stop by to photograph the building (always have a camera with me)just to get the security guard to come out and tell me I can''t.  While it''s true, the photos can''t be used for commercial purposes without owners permission they can be used to sell as prints or enter in photo challenges all you want.  What gets me so fired up about Chevron is them having an employee come out and tell you it''s illegal to photograph the build and insist you stop doing it.  Which is completely false as it''s perfectly legal to photograph anything from public property and the sidewalk is public property.  I tell them every time to call the police if they feel I am breaking the law or to leave me alone or I will call the police for harassment.  I have yet to have them call the police and each time they stop trying to talk with me and just stand there and watch............which makes shooting at night so much safer.  When there at night I always thank the employee (who is just doing his job and doesn''t want to be out there anyways) for watching after me and making sure I am safe.  Will usually tweet a thank you for Chevron being so concerned about my safety that they provide me with a guard.', '2017-05-02 10:53:51.000000', NULL, 0),
(7597609, 1186591, 117099, '<td valign="top">Very beautiful!</td>', 'Very beautiful!', '2018-09-25 12:34:46.000000', NULL, 0);
